    for (let i = 0; i < 16; i++) { const a = i / 16 * Math.PI * 2; ctx.strokeStyle = ['rgba(183,52,42,.35)', 'rgba(60,110,70,.35)', 'rgba(42,29,21,.3)'][i % 3]; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(qx, qy); ctx.lineTo(qx + Math.cos(a) * w * 1.4, qy + Math.sin(a) * w * 1.4); ctx.stroke(); }
